INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7d5ac2d4-a1b6-496b-929e-cb87ad12b530', 'Late Fees', '4', '4', 'CONTRAPRESTACIÓN', E'- If the subtenant does not pay the rent within the first ten days of the month, late fees will start to accumulate from the eleventh day.\n- The late fees are calculated at a rate of 4% per month, prorated for the time the payment is late.\n- If there are outstanding rent or interest payments, any payment made by the subtenant will first cover the interest, and any remaining amount will go towards the overdue rent.', 'En caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas ò intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7d5ac2d4-a1b6-496b-929e-cb87ad12b530', 'Incremento de Renta', '4', '5', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase starting in the third year of operation.\n- The first increase will occur in the 25th month of operation.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or its equivalent.\n- Annual increases are capped at a maximum of 8% of the current payment amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL incrementará a partir del tercer año de operación del ÁREA COMERCIAL y a partir de esta fecha se aumentará Anualmente. Detallando lo anterior, las Partes acuerdan que el primer incremento se realizará hasta el mes veinticinco (25) de operación del ÁREA COMERCIAL,, y será en la misma proporción en que aumenté el Índice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho período.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7d5ac2d4-a1b6-496b-929e-cb87ad12b530', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include the applicable value-added tax (VAT) or any future tax that replaces it.\n- The subtenant will not contribute to the shopping center''s advertising expenses, so no advertising costs will be charged to them.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. Las Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7d5ac2d4-a1b6-496b-929e-cb87ad12b530', 'Maintenance - Tenant', '5', '6', 'DEL MANTENIMIENTO Y PREVENCIÓN DE RIESGOS', E'- The subtenant agrees to take care of, preserve, and maintain the commercial area and any installations made there.\n- This responsibility is at the subtenant''s own expense.\n- These obligations apply throughout the duration of the sublease.', 'EL SUBARRENDATARIO se obliga durante la vigencia del presente subarrendamiento, a su costa exclusiva, el cuidado, conservación y mantenimiento que requiera EL ÁREA COMERCIAL y las instalaciones que en ella realice.');
