INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('15fe915d-ff1b-4bc5-99a4-6aff88b03286', 'Late Fees', '2', '3', 'INTERESES MORATORIOS', E'- If the tenant is late in paying any money or monthly rent owed to the landlord, they must pay late interest.\n- The late interest is calculated by multiplying the amount owed by the annual rate of 28-day treasury certificates (CETES) plus an additional 10% per year.\n- This interest is calculated monthly using the average CETES rate published by the Bank of Mexico in the last week of each month.\n- The landlord still retains the right to demand timely rent payment or terminate the contract, as well as to enforce any other rights due to the late payment.', 'En caso de mora en el pago de cualquier cantidad de dinero o renta mensual adeudada por "EL ARRENDATARIO" a "LA ARRENDADORA", "EL ARRENDATARIO" deberá pagar a "LA ARRENDADORA" Intereses moratorios mensuales equivalentes a la cantidad que resulte de multiplicar a la cantidad adeudada, la tasa anual equivalente a certificados de la tesorería (CETES) a 28 días más 10 puntos porcentuales anuales sobre saldos Insolutos, que se calculará mensualmente, utilizando la tasa (CETES) promedio publicada por el Banco de México en la última semana de cada mes o aquella que la sustituya, sin que esto implique renuncia alguna a la facultad que para tal supuesto "LA ARRENDADORA" tendrá para exigir el pago puntual de la renta o para rescindir este contrato; así como para exigir y/o deducir cualesquiera otro derecho que por tal motivo le resulte.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('15fe915d-ff1b-4bc5-99a4-6aff88b03286', 'Incremento de Renta', '1', '2', 'DEL MONTO, FORMA, FECHA Y LUGAR DE PAGO DE RENTA Y MANTENIMIENTO', E'- Durante los primeros 6 meses después del segundo periodo de gracia, la renta mensual será de $5,833.50 USD.\n- Después de esos 6 meses, la renta mensual aumentará a $11,667.00 USD.\n- El pago puede hacerse en dólares americanos o en pesos, usando el tipo de cambio del día anterior publicado en el diario oficial.\n- Los importes incluyen el Impuesto al Valor Agregado (IVA).', 'Las partes acuerdan que el Importe de renta mensual que se pagará por los primeros 6 (seis) meses posteriores a la fecha de terminación de segundo periodo de gracia señalado más adelante en esta cláusula, será de $5,833.50 dólares americanos; estableciendo que una vez transcurrido este único periodo seis meses, la renta mensual que se deberá pagar será de $11,667.00 dólares americanos. Las partes acuerdan que el pago podrá realizarse en dólares americanos o su equivalente en pesos al tipo de cambio publicado en el diario oficial de la federación, al día anterior al de fecha de pago, Importes adicionados con el Impuesto al Valor Agregado.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('15fe915d-ff1b-4bc5-99a4-6aff88b03286', 'Common Area Maintenance Charges', '2', '2', 'PAGO DE MANTENIMIENTO', E'- The tenant must pay the landlord a monthly maintenance fee.\n- This fee is 10% of the rent for the commercial space, plus applicable VAT.\n- Payment is due throughout the lease term and until the tenant returns the commercial space to the landlord.\n- Common areas include parking, sewers, pathways, ramps, entrances, hallways, rooftops, gardens, plazas, stairs, and any shared equipment.\n- Maintenance costs cover the upkeep and operation of parking and other common areas.\n- The maintenance fee does not cover taxes, government fees, or maintenance of the commercial space itself.\n- The tenant will start paying the maintenance fee after the agreed grace period ends.', '"EL ARRENDATARIO" tendrá la obligación de pagar a "LA ARRENDADORA" mensualmente a la fecha de pago de renta y por concepto de cuota de Mantenimiento el valor que resulte de multiplicar el 10% del valor de la renta de "EL LOCAL COMERCIAL" más el correspondiente Impuesto al Valor Agregado, a nombre de "LA ARRENDADORA" o de quien esta designe, durante todo el tiempo de vigencia del presente contrato y mientras "EL ARRENDATARIO" no haga entrega de "EL LOCAL COMERCIAL" a "LA ARRENDADORA", en los términos de este instrumento. Para efecto de este contrato se entiende como áreas comunes los estacionamientos, alcantarillas, vías de comunicación, rampas, entradas, pasillos pórticos, azoteas, jardineras, plazas, escaleras y cualquier otro equipo de Instalación de uso común. El costo del mantenimiento de las áreas comunes incluye el mantenimiento y operación del estacionamiento en todas sus áreas y del resto de las áreas comunes. La cuota de mantenimiento no Incluye impuestos, servicios o cuotas de ninguna dependencia de gobierno generado directamente o indirectamente por el "EL ARRENDATARIO”, tampoco incluye ningún tipo de mantenimiento de "EL LOCAL COMERCIAL” De mutuo acuerdo las partes establecen, que “EL ARRENDATARIO" deberá pagar el monto del mantenimiento establecido, una vez que finalice el primer periodo de gracia pactado en la presente clausula.');
